{"code": "await tools.dst.act({action:"move",x:-359,z:-243});
await tools.dst.act({action:"wait",seconds:7});
let o=await tools.dst.observe();
const p1=[+o.state.x.toFixed(1),+o.state.z.toFixed(1)];
// pick nearest grass and sapling
const g=o.state.nearby.find(e=>e.prefab==="grass"&&e.pickable);
const s=o.state.nearby.find(e=>e.prefab==="sapling"&&e.pickable);
if(g) await tools.dst.act({action:"pick",target:g.id});
if(s) await tools.dst.act({action:"pick",target:s.id});
await tools.dst.act({action:"wait",seconds:4});
o=await tools.dst.observe();
return {p1,p2:[+o.state.x.toFixed(1),+o.state.z.toFixed(1)],t:+o.state.time.toFixed(1),phase:o.state.phase,inv:o.state.inventory.map(i=>i.prefab+":"+i.count+(i.id?"#"+i.id:"")),last:o.state.last_action};"}

